/* Wave 5, Phase 2: inline the casting data into Session-Sketch.html as script
   block 1a, generated from wave5-jobs.js (the single source of truth).
   Browser-safe: JOBS -> AIJOB (array) + AIJOB_BY_KEY (map), plus ARC/ARCPHASE.
   jobsFor() is deliberately NOT copied — see design doc §11.4.
   Idempotent: replaces between markers if already present. node build-jobs-inline.js */
var fs = require("fs");
var jobs = require("./wave5-jobs.js");

var block =
  '<!-- wave5-jobs:start (generated by build-jobs-inline.js from wave5-jobs.js — do not hand-edit) -->\n'+
  '<script>\n"use strict";\n'+
  '/* Wave 5 — AI casting data, inlined from wave5-jobs.js. Nothing here scores;\n'+
  '   the casting is chosen after the tag. jobsFor() is intentionally not copied\n'+
  '   (design doc §11.4). Re-inline with: node build-jobs-inline.js */\n'+
  'var ARC = '+JSON.stringify(jobs.ARC)+';\n'+
  'var ARCPHASE = '+JSON.stringify(jobs.ARCPHASE)+';\n'+
  'var AIJOB = '+JSON.stringify(jobs.JOBS)+';\n'+
  'var AIJOB_BY_KEY = {}; (function(){ for(var i=0;i<AIJOB.length;i++) AIJOB_BY_KEY[AIJOB[i].k]=AIJOB[i]; })();\n'+
  '</script>\n'+
  '<!-- wave5-jobs:end -->';

var FILE = "Session-Sketch.html";
var s = fs.readFileSync(FILE, "utf8");
var before = s.length;

var START = "<!-- wave5-jobs:start", END = "<!-- wave5-jobs:end -->";
if (s.indexOf(START) > -1) {
  var a = s.indexOf(START), b = s.indexOf(END) + END.length;
  s = s.slice(0, a) + block + s.slice(b);
  console.log("replaced existing block 1a");
} else {
  var idx = s.indexOf("RAW MATERIAL");
  if (idx < 0) throw new Error("could not find the MAT block (RAW MATERIAL)");
  var at = s.lastIndexOf("<script>", idx);
  if (at < 0) throw new Error("could not find the <script> before MAT");
  s = s.slice(0, at) + block + "\n" + s.slice(at);
  console.log("inserted block 1a before the MAT block");
}

if (!/<\/html>\s*$/.test(s)) throw new Error("file no longer ends with </html>");
fs.writeFileSync(FILE, s, "utf8");

/* self-check: the inlined data must parse and hold 12 castings */
var m = s.match(/var AIJOB = (\[[\s\S]*?\]);\n/);
if (!m) throw new Error("could not read back AIJOB");
var arr = JSON.parse(m[1]);
console.log("wrote "+FILE+"  ("+before+" -> "+s.length+" bytes); castings inlined: "+arr.length);
if (arr.length !== 12) throw new Error("expected 12 castings, got "+arr.length);
